ALTER TABLE public.bunny_security_checks ADD COLUMN library_id text;
CREATE OR REPLACE FUNCTION public.lms_bunny_playback_mapping(p_lesson uuid,p_hash text) RETURNS TABLE(encrypted_video text,library_id text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid text:=auth.jwt()->>'session_id'; BEGIN
IF auth.uid() IS NULL OR sid IS NULL OR NOT EXISTS(SELECT 1 FROM auth.sessions WHERE id::text=sid AND user_id=auth.uid()) THEN RAISE EXCEPTION 'Sign in again'; END IF;
IF EXISTS(SELECT 1 FROM public.registered_devices WHERE user_id=auth.uid() AND session_id=sid AND revoked_at IS NOT NULL) OR NOT EXISTS(SELECT 1 FROM public.registered_devices WHERE user_id=auth.uid() AND session_id=sid AND token_hash=p_hash AND revoked_at IS NULL) THEN RAISE EXCEPTION 'Registered active browser required'; END IF;
IF NOT EXISTS(SELECT 1 FROM public.bunny_security_checks WHERE id=true AND embed_tokens AND preview_referrer AND unsigned_denied AND direct_media_denied AND verified_at>now()-interval '24 hours') THEN RAISE EXCEPTION 'Bunny security configuration unverified'; END IF;
RETURN QUERY SELECT v.encrypted_video,v.library_id FROM public.lesson_bunny_videos v JOIN public.bunny_security_checks s ON s.id=true AND s.library_id=v.library_id JOIN public.lessons l ON l.id=v.lesson_id JOIN public.modules m ON m.id=l.module_id JOIN public.courses c ON c.id=m.course_id JOIN public.enrollments e ON e.course_id=c.id WHERE l.id=p_lesson AND l.status='published' AND c.status='published' AND e.user_id=auth.uid() AND e.starts_at<=now() AND e.expires_at>now() AND e.revoked_at IS NULL;
END $$;